package org.securemail.client.storage;
import static org.junit.jupiter.api.Assertions.*;
import java.io.IOException;import java.nio.file.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
import org.securemail.client.ecosystem.ComponentInstallation;
/** Actual filesystem/image-plan tests; fixture executables are never executed. Windows native NOT_RUN. */
class UpdateSupportWindows600Test {
 @TempDir Path temp;private Path local,program,profile,current,launcher,source,old;
 @BeforeEach void setup()throws Exception{local=temp.resolve("Local Data");program=local.resolve("Programs/AEGIS");profile=temp.resolve("private profile");current=program.resolve("runtime/bin/javaw.exe");launcher=program.resolve("AEGIS.exe");source=program.resolve("AEGIS-Maintenance.exe");old=program.resolveSibling("AEGIS.rollback-6.0.0");Files.createDirectories(current.getParent());Files.createDirectories(old);Files.writeString(current,"public fixture java image");Files.writeString(launcher,"public fixture launcher");Files.writeString(source,"public fixture helper bytes never executed");Files.writeString(old.resolve("AEGIS.exe"),"public previous launcher fixture");inventory();}
 private void inventory()throws Exception{Files.writeString(program.resolve("maintenance600.json"),"{\"schema\":1,\"sha256\":\""+ComponentInstallation.sha256(source)+"\",\"sourceCommit\":\""+"a".repeat(40)+"\"}");}
 private Optional<UpdateSupport.WindowsRollbackPlan600> plan()throws Exception{return UpdateSupport.rollbackPlan600(program,local,profile,current,12,launcher,11);}
 @Test void exactCoreImagesAndSixSuffixProduceReadOnlyPlan()throws Exception{var p=plan().orElseThrow();assertEquals(old,p.previous());assertEquals(profile.resolve("tmp"),p.temporary());assertFalse(Files.exists(profile));assertEquals(12,p.clientPid());assertEquals(11,p.launcherPid());}
 @Test void childMailParentOrOtherJvmCannotScheduleProgramReplacement()throws Exception{assertTrue(UpdateSupport.rollbackPlan600(program,local,profile,current,12,current,11).isEmpty());assertTrue(UpdateSupport.rollbackPlan600(program,local,profile,program.resolve("runtime/bin/java.exe"),12,launcher,11).isEmpty());assertTrue(UpdateSupport.rollbackPlan600(program,local,profile,current,12,launcher,12).isEmpty());assertTrue(UpdateSupport.rollbackPlan600(program,local,profile,current,-1,launcher,11).isEmpty());}
 @Test void portableOrUserSelectedProgramFolderCannotBeRolledBack()throws Exception{assertTrue(UpdateSupport.rollbackPlan600(temp.resolve("portable"),local,profile,current,12,launcher,11).isEmpty());assertTrue(UpdateSupport.rollbackPlan600(program,temp.resolve("other local"),profile,current,12,launcher,11).isEmpty());}
 @Test void missingPreviousLauncherDoesNotFallBackToLegacySuffix()throws Exception{Files.delete(old.resolve("AEGIS.exe"));Path legacy=program.resolveSibling("AEGIS.rollback-1.1.5");Files.createDirectories(legacy);Files.writeString(legacy.resolve("AEGIS.exe"),"legacy");assertTrue(plan().isEmpty());}
 @Test void changedOrUnpinnedHelperCannotRun()throws Exception{Files.writeString(source,"tampered public helper");assertThrows(IOException.class,this::plan);inventory();Files.delete(program.resolve("maintenance600.json"));assertThrows(IOException.class,this::plan);}
 @Test void ambiguousOrOversizedInventoryCannotConferTrust()throws Exception{for(String wrong:List.of("{\"schema\":1.1,\"sha256\":\""+"a".repeat(64)+"\",\"sourceCommit\":\""+"b".repeat(40)+"\"}","{\"schema\":1,\"schema\":1}","{\"schema\":1,\"sha256\":{},\"sourceCommit\":{}}","x".repeat(4097))){Files.writeString(program.resolve("maintenance600.json"),wrong);assertThrows(IOException.class,this::plan);}}
 @Test void helperAndPreviousLinksAreRejectedBeforeCopy()throws Exception{Path alternate=temp.resolve("alternate");Files.writeString(alternate,"untrusted");Files.delete(source);try{Files.createSymbolicLink(source,alternate);}catch(UnsupportedOperationException|FileSystemException unavailable){Assumptions.abort("Symlink unavailable");}assertThrows(IOException.class,this::plan);assertFalse(Files.exists(profile));}
 @Test void helperStagingOutsideProgramPreservesBytesAndUsesFiveFixedArguments()throws Exception{var p=plan().orElseThrow();Path helper=UpdateSupport.stageRollbackHelper600(p);assertTrue(helper.startsWith(profile.resolve("tmp")));assertFalse(helper.startsWith(program));assertEquals(ComponentInstallation.sha256(source),ComponentInstallation.sha256(helper));assertEquals(List.of(helper.toString(),"--prepare-rollback",program.toString(),"12","11"),UpdateSupport.rollbackCommand600(p,helper));if(Files.getFileStore(helper).supportsFileAttributeView("posix"))assertEquals(java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"),Files.getPosixFilePermissions(helper));}
 @Test void sourceMutationAfterPreflightCannotReachLaunch()throws Exception{var p=plan().orElseThrow();Files.writeString(source,"later changed helper");assertThrows(IOException.class,()->UpdateSupport.stageRollbackHelper600(p));assertFalse(Files.exists(profile));}
 @Test void tempDirectoryInsideProgramOrPreviousCopyFailsClosed()throws Exception{assertThrows(IOException.class,()->UpdateSupport.rollbackPlan600(program,local,program.resolve("private"),current,12,launcher,11));assertThrows(IOException.class,()->UpdateSupport.rollbackPlan600(program,local,old.resolve("private"),current,12,launcher,11));}
 @Test void unsupportedHostNeverAttemptsNativeRollback()throws Exception{Assumptions.assumeFalse(System.getProperty("os.name").startsWith("Windows"));assertFalse(UpdateSupport.canWindowsRollback600());assertFalse(UpdateSupport.scheduleWindowsRollback600());}
}
